import type { SacredText, Verse } from '../types';

const b = (te: string, en: string) => ({ te, en });
/** One block of a song: optional heading, Telugu-script lyric, English meaning, simple Telugu bhavam. */
const V = (h: string | null, te: string, en: string, bhavam?: string): Verse => ({
  ...(h ? { heading: HEAD[h] ?? b(h, h) } : {}),
  te,
  en,
  ...(bhavam ? { bhavam } : {}),
});
const HEAD: Record<string, { te: string; en: string }> = {
  P: b('పల్లవి', 'Pallavi'),
  A: b('అనుపల్లవి', 'Anupallavi'),
  C: b('చరణం', 'Charanam'),
  C1: b('చరణం 1', 'Charanam 1'),
  C2: b('చరణం 2', 'Charanam 2'),
  C3: b('చరణం 3', 'Charanam 3'),
  C4: b('చరణం 4', 'Charanam 4'),
  C5: b('చరణం 5', 'Charanam 5'),
};

